-- Keep the source-verified content agent cron target aligned with this Supabase project.
-- The historical 20260821175933 migration used a legacy project ref. Production
-- has already been reconciled manually; this idempotent migration keeps clean
-- database replays and future environments on the current project as well.
--
-- No content is fetched or generated by this migration. It only reconciles the
-- pg_cron command. The scheduled job remains daily at 03:00 UTC and continues
-- to authenticate through the server-side scheduler secret RPC.

DO $do$
DECLARE
  v_cron_job_oid regclass := to_regclass('cron.job');
BEGIN
  IF v_cron_job_oid IS NULL THEN
    RETURN;
  END IF;

  -- Some local migration-test environments expose a minimal cron.job stub.
  -- Skip reconciliation unless the deployed pg_cron contract is complete.
  IF (
    SELECT count(*)
    FROM pg_attribute
    WHERE attrelid = v_cron_job_oid
      AND attname IN ('jobid', 'jobname', 'command', 'schedule', 'active')
      AND NOT attisdropped
  ) <> 5
    OR to_regprocedure('cron.alter_job(bigint,text,text,text,text,boolean)') IS NULL
    OR to_regprocedure('cron.unschedule(bigint)') IS NULL
    OR to_regprocedure('cron.schedule(text,text,text)') IS NULL
  THEN
    RETURN;
  END IF;

  EXECUTE $schedule$
    DO $inner$
    DECLARE
      v_job_ids bigint[];
      v_job_count bigint;
      v_job_id bigint;
      v_command text;
      v_schedule text;
      v_active boolean;
      v_target_url constant text := 'https://zqtssvlvmkzeeyqghqfk.supabase.co/functions/v1/source-verified-content-agent';
      v_job_command constant text := $command$
        SELECT net.http_post(
          url := 'https://zqtssvlvmkzeeyqghqfk.supabase.co/functions/v1/source-verified-content-agent',
          headers := jsonb_build_object(
            'Content-Type', 'application/json',
            'Authorization', 'Bearer ' || public.get_push_scheduler_secret()
          ),
          body := jsonb_build_object('source', 'pg_cron')
        );
      $command$;
    BEGIN
      SELECT array_agg(jobid ORDER BY jobid), count(*)
        INTO v_job_ids, v_job_count
      FROM cron.job
      WHERE jobname = 'zikr-source-verified-content-agent';

      IF v_job_count = 1 THEN
        SELECT jobid, command, schedule, active
          INTO v_job_id, v_command, v_schedule, v_active
        FROM cron.job
        WHERE jobname = 'zikr-source-verified-content-agent'
        ORDER BY jobid DESC
        LIMIT 1;

        IF v_command LIKE '%' || v_target_url || '%'
          AND v_schedule = '0 3 * * *'
          AND v_active THEN
          RETURN;
        END IF;

        PERFORM cron.alter_job(
          job_id := v_job_id,
          schedule := '0 3 * * *',
          command := v_job_command,
          active := true
        );
        RETURN;
      END IF;

      IF v_job_ids IS NOT NULL THEN
        FOREACH v_job_id IN ARRAY v_job_ids LOOP
          PERFORM cron.unschedule(v_job_id);
        END LOOP;
      END IF;

      PERFORM cron.schedule(
        'zikr-source-verified-content-agent',
        '0 3 * * *',
        v_job_command
      );
    END
    $inner$;
  $schedule$;
END

$do$;
